async function mpFn(b){const r=await fetch(SUPA_URL+'/functions/v1/mp-pagar',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPA_KEY,Authorization:'Bearer '+SUPA_KEY},body:JSON.stringify(b)});const j=await r.json().catch(()=>({}));if(!r.ok||j.erro)throw new Error(j.erro||'Não foi possível falar com o Mercado Pago.');return j}
