function chatAbrir(mode,num,tel,loja){chatFechar();let tit='Pedido nº '+num;
 if(mode==='loja'){const p=(PL||[]).find(x=>String(x.numero)===String(num));if(p)tit+=' · '+p.cliente}
 else{const o=OL.find(x=>String(x.n)===String(num))||ld('vv_ped',[]).find(x=>String(x.n)===String(num));if(!tel&&o)tel=o.t;if(!loja&&o)loja=o.lj;if(loja)tit+=' · '+loja}
 const z=document.createElement('div');z.id='chat';
 z.innerHTML='<div class="chh"><button class="chx" onclick="chatFechar()" aria-label="Voltar">←</button><b>'+esc(tit)+'</b></div><div class="chm" id="chm"><p class="hint" style="text-align:center">Carregando…</p></div><form id="chf" onsubmit="return chatEnv(event)"><input name="t" maxlength="500" autocomplete="off" placeholder="Escreva sua mensagem" required><button class="btn">Enviar</button></form><p class="chn">🔒 Telefone e links não são entregues no chat.</p>';
 document.body.appendChild(z);document.body.style.overflow='hidden';
 CH={mode:mode,num:num,tel:tel||'',last:0};chatPull(true);CH.tm=setInterval(()=>{if(!document.hidden)chatPull()},5000)}
function chatPull(first){const c=CH;if(!c)return;(c.mode==='loja'?run('chatListarLoja',A,c.num,c.last):run('chatListarCli',c.num,c.tel,c.last)).then(r=>{if(CH!==c)return;const m=$('chm');if(!m)return;if(first)m.innerHTML='';
  const bt=first||m.scrollHeight-m.scrollTop-m.clientHeight<80;
  r.msgs.forEach(x=>{c.last=Math.max(c.last,x.id);const me=(c.mode==='loja'?'loja':'cliente')===x.de;m.insertAdjacentHTML('beforeend','<div class="bb '+(x.de==='sistema'?'sys':x.b?'me blk':me?'me':'you')+'" data-id="'+x.id+'">'+esc(x.t).replace(/\n/g,'<br>').replace(/\u{1F3F7}\uFE0F?/gu,CPI)+(x.b?'<em class="bkn">🚫 Bloqueada: telefone, links e @ não são entregues no chat.</em>':'')+'<small>'+esc(x.h)+(me&&!x.b?' <span class="tk">✓</span>':'')+'</small></div>')});
  (r.vistas||[]).forEach(o=>{const bb=m.querySelector('.bb[data-id="'+o.id+'"]'),e=bb&&bb.querySelector('.tk');if(e&&e.textContent!=='✓✓'){e.textContent='✓✓';e.classList.add('rd');const d0=(bb.querySelector('small').firstChild.textContent||'').trim().slice(0,5),vv=String(o.v||''),vt=vv.slice(0,5)===d0?vv.slice(6):vv;e.insertAdjacentHTML('beforebegin',' · visto '+esc(vt))}});
  if(first&&!r.msgs.length)m.innerHTML='<p class="hint" style="text-align:center">Nenhuma mensagem ainda. Escreva abaixo.</p>';
  if(!r.aberto&&!$('chc'))m.insertAdjacentHTML('beforeend','<p class="hint" id="chc" style="text-align:center">Este chat está fechado.</p>');
  const f=$('chf');if(f)f.style.display=r.aberto?'flex':'none';if(bt)m.scrollTop=m.scrollHeight}).catch(x=>{if(first&&$('chm'))$('chm').innerHTML='<p class="msg err">'+esc(x.message)+'</p>'})}
function chatEnv(e){e.preventDefault();const c=CH,f=e.target,t=f.t.value.trim();if(!c||!t)return false;const bt=f.querySelector('button');bt.disabled=true;
 (c.mode==='loja'?run('chatEnviarLoja',A,c.num,t):run('chatEnviarCli',c.num,c.tel,t)).then(()=>{f.t.value='';chatPull()}).catch(x=>toast(x.message)).finally(()=>{bt.disabled=false;f.t.focus()});return false}
function chatFechar(){if(CH){clearInterval(CH.tm);CH=null}const z=$('chat');if(z)z.remove();document.body.style.overflow='';if(A)pedL();cliBadge();if($('pdl')&&$('ped').classList.contains('on'))pedCarregar()}

/* ---------- Documentos ---------- */
const TXT={t:'<h3>1. Quem somos</h3><p>A ValeShop Sobradinho é uma vitrine digital que reúne lojas e comerciantes de Sobradinho (BA). Responsável pela plataforma: Jocecino José dos Santos Filho. Contato: e-mail valeshopsobradinho@gmail.com ou Instagram @valeshop_sobradinho.</p><h3>2. Papel da plataforma</h3><p>Somos intermediários: apresentamos produtos e aproximamos clientes e lojas. A venda é feita entre o cliente e a loja. A plataforma não vende e não entrega os produtos. O pagamento é feito pelo Mercado Pago (Pix, cartão ou saldo), depois que a loja aceita o pedido: o valor vai direto para a conta Mercado Pago da loja, e a plataforma recebe apenas uma comissão sobre os produtos vendidos, descontada automaticamente no pagamento. O frete não entra na comissão. Estornos e devoluções de valores são feitos pelo Mercado Pago, conforme as regras dele.</p><h3>3. Cadastro de lojas</h3><ul><li>O cadastro depende de aprovação e é aceito apenas para lojas das cidades atendidas.</li><li>A loja declara que os dados e a logo enviados são verdadeiros e que tem direito de usá-los.</li><li>A loja é responsável por preços, estoque, qualidade, prazos, entrega e atendimento, conforme o Código de Defesa do Consumidor.</li><li>É proibido anunciar produtos ilegais, falsificados, perigosos ou cuja venda dependa de autorização que a loja não tenha.</li><li>Podemos recusar, suspender ou banir lojas que descumpram estes termos.</li><li>As perguntas feitas nos produtos são enviadas à loja; as respostas ficam visíveis para todos. Podemos ocultar conteúdo ofensivo.</li><li>Ofertas relâmpago duram no máximo 2 dias e ofertas de Black Friday no máximo 7 dias. O preço anunciado deve ser honrado pela loja.</li></ul><h3>4. Pedidos</h3><ul><li>Depois que a loja aceita o pedido, o cliente tem 24 horas para pagar pelo Mercado Pago. Sem pagamento nesse prazo, o pedido é cancelado e os produtos voltam para a vitrine. A loja só deve entregar pedidos que aparecem como pagos.</li><li>O nome completo, o endereço e o WhatsApp do cliente são liberados para a loja depois do pagamento. É proibido combinar a venda ou o pagamento fora da plataforma; a loja que fizer isso pode ser suspensa.</li><li>O pedido é registrado na plataforma e deve ser aceito pela loja. A loja tem 24 horas para aceitar o pedido (contadas a partir da abertura, se o pedido foi feito com a loja fechada). Sem confirmação, o pedido é cancelado e o estoque volta à vitrine.</li><li>Com a loja fechada, o pedido pode ser feito e será visto quando a loja abrir; o prazo de entrega informado pela loja conta a partir da abertura.</li><li>Frete e taxas são definidos por cada loja. Trocas, devoluções e cancelamentos são tratados diretamente com a loja.</li><li>A nota de compra é um comprovante sem valor fiscal.</li></ul><h3>5. Contato com clientes e uso dos dados</h3><ul><li>A conversa sobre o pedido deve acontecer pelo chat do app. O nome completo, o endereço e o WhatsApp do cliente só são liberados à loja depois que o pagamento é confirmado.</li><li>Os dados do cliente (nome, WhatsApp e endereço) são entregues à loja <b>somente para atender aquele pedido</b>: confirmar, combinar entrega, avisar o andamento e tirar dúvidas sobre ele.</li><li>É proibido à loja usar esses dados para outro fim: enviar promoções ou mensagens em massa, incluir o cliente em listas ou grupos, vender ou repassar os dados a terceiros, sem consentimento claro do cliente.</li><li>É proibido à loja usar o app apenas para captar clientes e levar a negociação para fora dele, ou pedir ao cliente que deixe de usar a plataforma para evitar regras, avaliações ou taxas.</li><li>O cliente deve usar o contato da loja apenas para assuntos do pedido e tratar a loja com respeito. Mensagens ofensivas, golpes ou spam levam ao bloqueio.</li><li>A loja trata os dados do cliente conforme a LGPD e responde por qualquer uso indevido. Denúncias podem ser feitas pelo contato acima e levam à suspensão ou ao banimento da loja.</li></ul><h3>6. Uso do aplicativo</h3><p>Não é permitido usar o app para fraudes, enviar dados falsos, tentar acessar áreas restritas ou prejudicar o funcionamento. A loja deve guardar sua senha e responde pelo uso da sua conta.</p><h3>7. Responsabilidade</h3><p>Não nos responsabilizamos por produtos, preços, prazos ou conduta das lojas, nem por falhas de internet ou de serviços de terceiros (como Supabase, Cloudflare e hospedagem), dentro do que a lei permitir.</p><h3>8. Alterações e foro</h3><p>Podemos atualizar estes termos; a versão vigente fica sempre neste endereço. Fica eleito o foro da comarca de Sobradinho (BA). Última atualização: 26/10/2026.</p>',
p:'<h3>1. Quem trata seus dados</h3><p>Controlador: ValeShop Sobradinho (responsável: Jocecino José dos Santos Filho). Contato para assuntos de privacidade: e-mail valeshopsobradinho@gmail.com ou Instagram @valeshop_sobradinho.</p><h3>2. Dados que coletamos</h3><ul><li><b>Clientes:</b> nome, WhatsApp, endereço de entrega (guardados no seu aparelho ou, se você criar conta, na sua conta, para preencher os próximos pedidos), itens do pedido, forma de pagamento e observações.</li><li><b>Conta do cliente (opcional):</b> nome, WhatsApp, e-mail (usado para confirmar a conta e recuperar a senha), endereço salvo e senha criptografada.</li><li><b>Chat do pedido:</b> as mensagens trocadas entre cliente e loja ficam guardadas junto ao pedido e podem ser analisadas pela administração em caso de denúncia ou disputa.</li><li><b>Lojas:</b> nome da loja e do responsável, WhatsApp, e-mail (para confirmar o cadastro e recuperar a senha), endereço, categoria, horários, logo, fotos de produtos e chave Pix. A senha é guardada de forma criptografada.</li><li>Dados salvos no seu aparelho (carrinho, favoritos, últimos dados de entrega e pedidos) para sua comodidade.</li><li><b>Estatísticas de uso:</b> páginas e produtos vistos, cliques e buscas, ligados a um código aleatório do aparelho, sem nome, telefone ou endereço. Servem para melhorar o app e mostrar resultados às lojas.</li></ul><h3>3. Para que usamos</h3><p>Para registrar e entregar pedidos, permitir contato entre cliente e loja, aprovar e administrar lojas, evitar fraudes e gerar estatísticas gerais de uso. As bases legais são a execução do pedido/contrato, o legítimo interesse e, quando necessário, o seu consentimento.</p><h3>4. Com quem compartilhamos</h3><p>Para que a loja escolhida atenda você, ela vê inicialmente o seu primeiro nome e o bairro; o nome completo, o endereço e o WhatsApp só são liberados para ela depois que o pagamento é confirmado. Usamos serviços de terceiros para funcionar: Supabase (banco de dados), Cloudflare (armazenamento das fotos e das cópias de segurança), Vercel (hospedagem) e Mercado Pago (processamento dos pagamentos; os dados do cartão são digitados direto no Mercado Pago e não passam pela plataforma). Não vendemos seus dados. A loja só pode usar os dados do seu pedido para atender esse pedido, e é proibido usá-los para enviar propaganda, formar listas ou repassá-los a outras pessoas; se isso acontecer, avise-nos pelo contato acima.</p><h3>5. Por quanto tempo</h3><p>Guardamos os dados pelo tempo necessário para atender os pedidos, cumprir obrigações legais e resolver disputas. Depois disso, eliminamos ou anonimizamos.</p><h3>6. Seus direitos (LGPD)</h3><p>Você pode pedir confirmação de tratamento, acesso, correção, anonimização ou exclusão dos dados, portabilidade e informações sobre compartilhamento, e retirar o consentimento. Fale conosco pelo contato acima.</p><h3>7. Segurança</h3><p>Usamos conexão segura, senhas criptografadas, limite de tentativas de acesso e acesso restrito à administração. Nenhum sistema é totalmente imune a falhas; em caso de incidente relevante, avisaremos os afetados.</p><h3>8. Crianças</h3><p>O app é destinado a maiores de 18 anos ou menores acompanhados por um responsável.</p><h3>9. Atualizações</h3><p>Esta política pode mudar; a versão atual fica sempre aqui. Última atualização: 26/10/2026.</p>'};
