function prodA(p){APD=p;run('adminProdutos',S,$('apq').value,p).then(r=>{const tp=Math.max(1,Math.ceil(r.total/30));APL=r.itens;
 const seen={},gs=[];r.itens.forEach(x=>{if(!x.gr)gs.push([x]);else{if(!seen[x.gr]){seen[x.gr]=[];gs.push(seen[x.gr])}seen[x.gr].push(x)}});
 $('apl').innerHTML='<p class="hint pd">'+nf(r.total)+' produto(s) · página '+p+' de '+tp+'</p>'+gs.map(g=>{const x=g[0];return '<div class="item'+(x.ativo?'':' off')+'" style="display:block"><div style="display:flex;gap:10px"><div class="th">'+(x.foto?'<img src="'+esc(x.foto)+'" alt="">':'🛍️')+'</div><div class="g"><b>'+esc(x.titulo)+'</b><small>🏪 '+esc(x.loja)+' · '+brl(x.preco)+' · estoque: '+(x.estoque==null?'—':x.estoque)+'</small>'+(g.length>1?'<small>🎨 '+g.length+' cores: '+g.map(c=>esc(c.cor||'sem nome')+(c.ativo?'':' (pausada)')).join(', ')+'</small>':(x.cor?'<small>Cor: '+esc(x.cor)+'</small>':''))+(x.ativo?'':'<small>'+(x.bloq?'🔒 Pausado pela administração':'⏸ Pausado pelo lojista')+'</small>')+'</div></div>'+
  '<div class="pb"><button class="btn s" onclick="go(\'produto/'+x.id+'\')">👁 Ver</button><button class="btn s'+(x.ativo?'':'')+'" onclick="admM(\''+x.id+'\',\''+(x.ativo?'pausar':'reativar')+'\')">'+(x.ativo?'⏸ Pausar':'▶ Reativar')+'</button><button class="btn s" style="color:var(--gold)" onclick="admM(\''+x.id+'\',\'avisar\')">⚠️ Avisar</button><button class="btn s" onclick="promoS(\''+x.id+'\')">⭐ Promover no slide</button><button class="btn s r" onclick="admM(\''+x.id+'\',\'remover\')">🗑 Remover</button></div></div>'}).join('')+'<div class="pd" style="display:flex;gap:8px;margin-bottom:20px">'+(p>1?'<button class="btn s" onclick="prodA('+(p-1)+')">‹ Anterior</button>':'')+(p<tp?'<button class="btn s" onclick="prodA('+(p+1)+')">Próxima ›</button>':'')+'</div>'}).catch(x=>say('apl',esc(x.message),1))}
