 (ac==='pausar'?'<p class="hint">O produto sai da vitrine e o lojista não consegue reativar sozinho.</p>':'')+(ac==='reativar'?'<p class="hint">O produto volta para a vitrine.</p>':'')+
 '<div id="am_msg"></div><div class="mbt"><button class="btn s r" id="am_c">Cancelar</button><button class="btn s" id="am_ok">'+({pausar:'Pausar',reativar:'Reativar',avisar:'Enviar aviso',remover:'Remover'})[ac]+'</button></div></div>';
 document.body.appendChild(m);const q=s=>m.querySelector(s);q('#am_c').onclick=()=>m.remove();m.onclick=e=>{if(e.target===m)m.remove()};
