async function pacote(id){const l0=AD.find(x=>x.id===id)||{};const v=await dlg({msg:'Novo limite de produtos ativos para '+l0.nome+':',input:true,val:String(l0.limite||''),ph:'Ex.: 30',ok:'Salvar',no:'Voltar'});if(v===null)return;const n=parseInt(String(v).trim(),10);if(!(n>=0&&n<=10000))return toast('Digite um número de 0 a 10000.');run('adminLojaLimite',S,id,n).then(()=>{toast('Pacote atualizado: '+n+' produtos.');return run('adminListar',S)}).then(l=>{AD=l;admRender()}).catch(x=>toast(x.message))}
async function decidir(id,acao){let motivo='';
 if(acao==='aprovar'&&!(((AD.find(x=>x.id===id)||{}).limite||0)>=1&&['suspensa','pausada','banida'].indexOf((AD.find(x=>x.id===id)||{}).status)>-1)){const l0=AD.find(x=>x.id===id)||{};const v=await dlg({msg:'Pacote da loja: quantos produtos ATIVOS ela pode ter?\n(Você pode mudar depois no botão Pacote.)',input:true,val:String(l0.limite||''),ph:'Ex.: 30',ok:'Aprovar',no:'Voltar'});if(v===null)return;const n=parseInt(String(v).trim(),10);if(!(n>=1&&n<=10000))return toast('Digite um número de 1 a 10000.');try{await run('adminLojaLimite',S,id,n)}catch(x){return toast(x.message)}}
 if(acao==='recusar'||acao==='banir'||acao==='suspender'){motivo=((await askTxtP('Motivo (será enviado ao lojista):'))||'').trim();if(!motivo)return}
 if(acao==='suspender'&&!(await dlg({msg:'Suspender esta loja? Ela e os produtos saem da vitrine e o lojista só volta com a sua autorização.',ok:'Suspender',no:'Voltar'})))return;
 if(acao==='banir'&&!(await dlg({msg:'Banir esta loja? Ela sai da vitrine.',ok:'Banir',no:'Voltar'})))return;
 say('aMsg','Salvando…');
 run('adminDecidir',S,id,acao,motivo).then(r=>{const n=r.responsavel||'';let t='';
  if(acao==='recusar')t='Olá'+(n?', '+n:'')+'! Obrigado pelo interesse na *ValeShop Sobradinho*.\n\nInfelizmente o cadastro da loja *'+r.nome+'* não foi aprovado desta vez.\n\n*Motivo:* '+motivo+'\n\nVocê pode corrigir as informações e fazer um novo cadastro em *Minha loja > Cadastre sua loja*:\n'+SITE+'\n\nQualquer dúvida, é só responder esta mensagem.';
  else if(acao==='aprovar')t='Olá'+(n?', '+n:'')+'! 🎉 Sua loja *'+r.nome+'* foi *aprovada* na ValeShop Sobradinho! Seu pacote: até *'+r.limite+' produtos ativos*.\n\nComo começar:\n1) Acesse: '+SITE+'\n2) Toque em *Lojista* e entre com o seu WhatsApp e a senha do cadastro\n3) Em *Loja*, confira horários, taxa de entrega por bairro e formas de pagamento\n4) Em *Produtos*, cadastre fotos, preço e estoque (roupas e calçados com os tamanhos)\n\nDica: use o botão *⚡ Oferta* para vender mais com uma oferta relâmpago, e responda as perguntas dos clientes na aba *Perguntas*.\n\nQualquer dúvida, é só responder esta mensagem.';
  else if(acao==='suspender')t='Olá'+(n?', '+n:'')+'! A loja *'+r.nome+'* foi *suspensa* na ValeShop Sobradinho.\n\nMotivo: '+motivo+'\n\nEnquanto estiver suspensa, ela não aparece na vitrine nem recebe pedidos novos. Para resolver, responda esta mensagem.';
  else if(acao==='banir')t='Olá'+(n?', '+n:'')+'! A loja *'+r.nome+'* foi removida da ValeShop Sobradinho.\n\nMotivo: '+motivo+'\n\nPara esclarecimentos, responda esta mensagem.';
  say('aMsg','Feito. '+(t?'<br><br><a class="buy" target="_blank" rel="noopener" href="'+wa(r.whatsapp,t)+'">Avisar o lojista no WhatsApp</a>':''));
  return run('adminListar',S)}).then(l=>{AD=l;admRender();carregar()}).catch(x=>say('aMsg',esc(x.message),1))}

